// One-time (idempotent) seed: demo accounts, their media, then a demo reset.
// Usage: node scripts/seed.mjs   (needs seed-media/, generated by scripts/make-media.sh)
import { readFileSync } from 'node:fs';
import { loadEnv, adminClient, allUsers, ALL_SEED_EMAILS, SEED_MEMBERS, passwordFor, resetDemo } from './lib.mjs';

const env = loadEnv();
const admin = adminClient(env);

const existing = new Map((await allUsers(admin)).map((u) => [u.email, u]));
const ids = {};
for (const email of ALL_SEED_EMAILS) {
  const password = passwordFor(email, env);
  if (existing.has(email)) {
    const u = existing.get(email);
    await admin.auth.admin.updateUserById(u.id, { password, email_confirm: true });
    ids[email] = u.id;
  } else {
    const { data, error } = await admin.auth.admin.createUser({ email, password, email_confirm: true });
    if (error) throw error;
    ids[email] = data.user.id;
  }
}
console.log(`accounts ready: ${Object.keys(ids).length}`);

const { error: daErr } = await admin.from('demo_accounts').upsert(ALL_SEED_EMAILS.map((email) => ({ email })));
if (daErr) throw daErr;

for (const name of SEED_MEMBERS) {
  const id = ids[`${name}@example.com`];
  for (const [file, dest, type] of [
    [`${name}-photo.jpg`, 'photo-seed.jpg', 'image/jpeg'],
    [`${name}-video.mp4`, 'video-seed.mp4', 'video/mp4'],
  ]) {
    const body = readFileSync(new URL(`../seed-media/${file}`, import.meta.url));
    const { error } = await admin.storage.from('media').upload(`${id}/${dest}`, body, { contentType: type, upsert: true });
    if (error) throw error;
  }
}
console.log('media uploaded');

await resetDemo(admin);
console.log('demo data reset');
